#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets these two at the top of the stages section.
TOTAL_STAGES=0
TOTAL_MINUTES=0

_STAGE_INDEX=0
_MINUTES_ELAPSED=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does and how long it takes.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · about %s minutes%s\n\n' \
    "$DIM" "$TOTAL_STAGES" "$TOTAL_MINUTES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" <minutes> — clear the screen, then announce a stage and show
# progress + time remaining. Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  local remaining=$((TOTAL_MINUTES - _MINUTES_ELAPSED))
  (( remaining < 0 )) && remaining=0
  _MINUTES_ELAPSED=$((_MINUTES_ELAPSED + ${2:-0}))
  printf '\n%s%s▸ Stage %s/%s · %s%s  %s(~%s min left)%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET" "$DIM" "$remaining" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — one stage() per step the human takes. Takes a fresh clone from
# "I have a Snowplow trial org" to a seeded pipeline, published Signals config,
# and (optionally) a live Vercel deployment. Re-runnable: re-pointing at a
# new org after a trial expires is the same procedure.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=12
TOTAL_MINUTES=60

# Everything runs from the repo root; the Next.js app lives in storefront/.
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"

ENV_FILE="storefront/.env.local"
BACKUP_DIR="$HOME/.signals-trial-backups"

usage() {
  printf 'Usage: %s [--from N]\n\n' "$(basename "$0")"
  printf '  --from N   resume at stage N, skipping the ones before it. Values you\n'
  printf '             already saved to %s are reused.\n\n' "$ENV_FILE"
  printf 'Stages:\n'
  grep -E '^if begin "' "${BASH_SOURCE[0]}" \
    | sed -E 's/^if begin "([^"]+)".*/  \1/' | nl -w2 -s'  '
  exit "${1:-0}"
}

START_STAGE=1
case "${1:-}" in
  --from)
    if [[ ! "${2:-}" =~ ^[0-9]+$ ]]; then
      printf 'Unknown argument: --from %s (expected a stage number)\n\n' "${2:-}" >&2
      usage 2
    fi
    START_STAGE="$2"
    if (( START_STAGE < 1 || START_STAGE > TOTAL_STAGES )); then
      printf 'Stage %s is out of range — this wizard has %s stages.\n\n' \
        "$START_STAGE" "$TOTAL_STAGES" >&2
      usage 2
    fi ;;
  --help|-h) usage ;;
  "") ;;
  *) printf 'Unknown argument: %s\n' "$1"; usage 2 ;;
esac

# Resuming past the stage that creates .env.local: start from the template so
# later stages never write into a bare file missing the commented defaults.
if (( START_STAGE > 3 )) && [[ ! -f "$ENV_FILE" ]]; then
  cp storefront/.env.example "$ENV_FILE"
  note "created $ENV_FILE from storefront/.env.example (resuming past stage 3)"
fi

# Values that belong to one specific Snowplow org. A new trial invalidates
# every one of them; AGENT_SHARED_SECRET, NEXT_PUBLIC_SNOWPLOW_APP_ID and
# NEXT_PUBLIC_CES_DEPLOYMENT_ID belong to the storefront/agent and survive.
ORG_SCOPED_KEYS=(
  SNOWPLOW_CONSOLE_API_KEY
  SNOWPLOW_CONSOLE_API_KEY_ID
  SNOWPLOW_CONSOLE_ORG_ID
  NEXT_PUBLIC_SNOWPLOW_COLLECTOR_URL
  NEXT_PUBLIC_SIGNALS_INTERVENTIONS_ENDPOINT
  SIGNALS_DEPLOYED_URL
)

# begin "Name" <minutes> — stage(), but returns non-zero when --from skips it.
# Wrap each stage body in `if begin ...; then ... fi`.
begin() {
  stage "$1" "$2"
  if (( _STAGE_INDEX < START_STAGE )); then
    note "skipped (resuming from stage $START_STAGE)"
    return 1
  fi
  return 0
}

# normalise_url URL — force https and drop any trailing slash.
#
# Console displays the collector as a bare hostname. Pasted in as-is, the tracker
# resolves it against the page protocol: on http://localhost the request goes out
# over http, the collector answers 308 to https with no Access-Control-Allow-Origin
# header, and since browsers never follow redirects on a CORS preflight, every
# event is blocked and shows up only as a console CORS error.
normalise_url() {
  local url="${1#"${1%%[![:space:]]*}"}"   # ltrim
  url="${url%"${url##*[![:space:]]}"}"     # rtrim
  url="${url%/}"
  [[ -z "$url" ]] && { printf ''; return; }
  case "$url" in
    https://*) printf '%s' "$url" ;;
    http://*)  printf 'https://%s' "${url#http://}" ;;
    *)         printf 'https://%s' "$url" ;;
  esac
}

# mask SECRET — show enough to spot a paste error, not enough to leak.
mask() {
  local s="$1" n=${#1}
  (( n == 0 )) && { printf '(empty)'; return; }
  (( n <= 8 )) && { printf '(%s chars)' "$n"; return; }
  printf '%s…%s (%s chars)' "${s:0:4}" "${s: -4}" "$n"
}

# _env_value KEY — value of KEY in ENV_FILE with any surrounding quotes stripped
# (values written by hand may be quoted; write_env never quotes).
_env_value() {
  local v; v=$(_existing "$1" || true)
  v="${v%\"}"; v="${v#\"}"; v="${v%\'}"; v="${v#\'}"
  # A template placeholder (e.g. "<your-collector-url>") counts as unset so
  # prompts don't offer it as a real value and skip-when-set logic skips it.
  case "$v" in "<"*">") v="" ;; esac
  printf '%s' "$v"
}

# _drop_env KEY — remove KEY from ENV_FILE so `ask` offers no stale default.
_drop_env() {
  local tmp; tmp=$(mktemp)
  grep -vE "^${1}=" "$ENV_FILE" > "$tmp" || true
  mv "$tmp" "$ENV_FILE"
}

# run "description" cmd... — echo then run, surfacing failures as a gate the
# human decides on rather than a silent abort.
run() {
  local desc="$1"; shift
  printf '  %s$%s %s\n' "$DIM" "$RESET" "$*"
  if "$@"; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$desc"
    return 0
  else
    local rc=$?
    warn "$desc failed (exit $rc)"
    return 1
  fi
}

# run_logged LOGFILE "description" cmd... — run, but also copy the output to
# LOGFILE so the caller can read the actual error after a failure instead of
# guessing at it. Relies on `set -o pipefail` so the tee doesn't mask the exit.
run_logged() {
  local log="$1" desc="$2"; shift 2
  printf '  %s$%s %s\n' "$DIM" "$RESET" "$*"
  if "$@" 2>&1 | tee "$log"; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$desc"
    return 0
  else
    local rc=$?
    warn "$desc failed (exit $rc)"
    return 1
  fi
}

# console_token — mint a short-lived Console bearer token from the API key in
# ENV_FILE, exactly as the Signals SDKs do. Prints the token; prints nothing
# and returns 1 if Console rejects the key, key ID or organization ID.
console_token() {
  local org kid key
  org=$(_env_value SNOWPLOW_CONSOLE_ORG_ID)
  kid=$(_env_value SNOWPLOW_CONSOLE_API_KEY_ID)
  key=$(_env_value SNOWPLOW_CONSOLE_API_KEY)
  [[ -n "$org" && -n "$kid" && -n "$key" ]] || return 1
  curl -sS --fail --max-time 20 \
    -H "X-API-Key-Id: $kid" -H "X-API-Key: $key" \
    "https://console.snowplowanalytics.com/api/msc/v1/organizations/$org/credentials/v3/token" 2>/dev/null \
    | sed -n 's/.*"accessToken" *: *"\([^"]*\)".*/\1/p' | grep .
}

# explain_key_scope — why Signals answers 401 for a key Console happily issued.
# Console API keys are scoped to the features ticked at creation, so a key
# without Signals gets a token but is refused by the Signals API. A Signals
# URL copied from another org fails the same way.
explain_key_scope() {
  warn "Signals rejected the Console API key (401 Unauthorized)."
  say  "Console issued a token, so the key is valid but Signals won't accept it."
  step "Check the key was created with every feature ticked, Signals included,"
  step "and that the Signals API URL is this org's (Console → Signals → Overview)."
  step "Then create a new key if needed and re-enter it in stage 4:"
  note "  ./scripts/setup-trial-org.sh --from 4"
}

# signals_preflight — prove the captured credentials work end to end before
# later stages spend time on them: mint a Console token, then make one
# read-only call to the Signals API with it. Returns 0 only when both succeed.
signals_preflight() {
  local url token code
  url=$(_env_value SIGNALS_DEPLOYED_URL)
  [[ -n "$url" ]] || { warn "SIGNALS_DEPLOYED_URL is empty — skipping the Signals check"; return 1; }
  if ! token=$(console_token); then
    warn "Console refused to issue a token for this API key — recheck the key, key"
    warn "ID and organization ID (stage 4)."
    return 1
  fi
  note "✓ Console issued a token for the API key"
  code=$(curl -sS -o /dev/null -w '%{http_code}' --max-time 20 \
    -H "Authorization: Bearer $token" "$url/api/v1/registry/services/" 2>/dev/null || printf '000')
  case "$code" in
    200) note "✓ Signals API at $url accepts the key"; return 0 ;;
    401) explain_key_scope; return 1 ;;
    000) warn "couldn't reach $url — check the Signals API URL (Console → Signals → Overview)"; return 1 ;;
    *)   warn "Signals API answered HTTP $code — is $url the Signals API base URL?"; return 1 ;;
  esac
}

banner "Snowplow trial org → seeded pipeline → live storefront"
note "Mistyped something? Every capture stage shows what you entered and lets you"
note "redo it before moving on. To restart later, ./scripts/setup-trial-org.sh --from N"
pause

# ── 1 ─────────────────────────────────────────────────────────────────────
if begin "Preflight — local tooling" 1; then
say "Checking the CLIs the later stages shell out to."
MISSING=()
for cmd in node npm python3 snowplow-cli openssl; do
  if command -v "$cmd" >/dev/null 2>&1; then
    note "✓ $cmd — $(command -v "$cmd")"
  else
    MISSING+=("$cmd"); warn "$cmd not found"
  fi
done
if command -v vercel >/dev/null 2>&1; then
  note "✓ vercel — $(command -v vercel)"
else
  warn "vercel not found — stages 11-12 fall back to the Vercel dashboard"
  SKIPPED+=("Vercel CLI not installed: npm i -g vercel, or use the dashboard")
fi
if (( ${#MISSING[@]} )); then
  warn "install these before continuing: ${MISSING[*]}"
  note "snowplow-cli: brew install snowplow-product/taps/snowplow-cli"
  confirm "Continue anyway?" || exit 1
fi
[[ -f storefront/package.json ]] || { warn "storefront/package.json missing — wrong directory?"; exit 1; }
note "repo root: $REPO_ROOT"
pause
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
if begin "Create (or sign in to) your Snowplow trial org" 10; then
say "A trial gives you a full pipeline (collector + enrich) plus Signals."
say "Already have a live trial org? Sign in and skip ahead — this stage just"
say "confirms the pipeline is live and Signals is enabled before you continue."
open_url "https://snowplow.io/get-started/snowplow-free-trial"
step "Sign up (or sign in) — use your work email. No card, no sales call."
step "Wait for the provisioning email / for the console to show a live pipeline."
step "In BDP Console, confirm Signals is enabled for the org (left nav → Signals)."
warn "Note the trial expiry date now — the pipeline stops computing when it lapses."
pause "Pipeline is live and Signals is enabled — press Enter."
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
if begin "Prepare storefront/.env.local" 1; then
if [[ -f "$ENV_FILE" ]]; then
  say "$ENV_FILE already exists. If it points at an org you are replacing, we"
  say "back it up outside the repo and blank the org-scoped keys so nothing"
  say "stale is kept."
  mkdir -p "$BACKUP_DIR"; chmod 700 "$BACKUP_DIR"
  BACKUP_PATH="$BACKUP_DIR/env.local.$(date +%Y%m%d-%H%M%S)"
  cp "$ENV_FILE" "$BACKUP_PATH"; chmod 600 "$BACKUP_PATH"
  note "backed up → $BACKUP_PATH"
  note "kept as-is: AGENT_SHARED_SECRET, NEXT_PUBLIC_SNOWPLOW_APP_ID, NEXT_PUBLIC_CES_DEPLOYMENT_ID"
  if confirm "Clear the ${#ORG_SCOPED_KEYS[@]} org-scoped keys in $ENV_FILE?"; then
    for key in "${ORG_SCOPED_KEYS[@]}"; do _drop_env "$key"; done
    printf '  %s✓%s cleared: %s\n' "$GREEN" "$RESET" "${ORG_SCOPED_KEYS[*]}"
  else
    note "left in place — each prompt offers the current value; Enter keeps it"
  fi
else
  say "Creating $ENV_FILE from storefront/.env.example."
  cp storefront/.env.example "$ENV_FILE"
fi
pause
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
if begin "Capture the Console API credentials" 4; then
open_url "https://console.snowplowanalytics.com"
while true; do
  step "The organization ID is the UUID in the console URL, right after the host."
  ask SNOWPLOW_CONSOLE_ORG_ID "Organization ID (UUID):"
  step "Manage organization → API keys → Create API key. The value shows once; copy it now."
  warn "Keys are scoped to the features you tick — tick everything at its top level."
  ask SNOWPLOW_CONSOLE_API_KEY_ID "API key ID (the visible identifier):"
  ask_secret SNOWPLOW_CONSOLE_API_KEY "API key (hidden input):"

  # Written before the confirm so a redo offers these as the Enter-default —
  # you retype only the one you got wrong.
  write_env SNOWPLOW_CONSOLE_ORG_ID "$SNOWPLOW_CONSOLE_ORG_ID"
  write_env SNOWPLOW_CONSOLE_API_KEY_ID "$SNOWPLOW_CONSOLE_API_KEY_ID"
  write_env SNOWPLOW_CONSOLE_API_KEY "$SNOWPLOW_CONSOLE_API_KEY"

  printf '\n'
  note "organization ID : $SNOWPLOW_CONSOLE_ORG_ID"
  note "API key ID      : $SNOWPLOW_CONSOLE_API_KEY_ID"
  note "API key         : $(mask "$SNOWPLOW_CONSOLE_API_KEY")"
  if confirm "All three correct?"; then
    if console_token >/dev/null; then
      note "✓ Console accepted the key and issued a token"
      break
    fi
    warn "Console refused to issue a token for these values — one of them is wrong."
    confirm "Keep them anyway?" && break
  fi
  warn "re-entering — press Enter at any prompt to keep the value shown"
done
pause
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
if begin "Capture the collector and Signals endpoints" 3; then
say "Two URLs: where the browser tracker sends events, and where Signals lives."
open_url "https://console.snowplowanalytics.com"
while true; do
  step "Collector: your pipeline's collector endpoint. Console shows it as a bare"
  step "hostname — paste it as shown, https:// is added for you."
  note "  e.g. trial-xxxxx-yyyyy.collector.snplow.net"
  ask NEXT_PUBLIC_SNOWPLOW_COLLECTOR_URL "Collector URL:"
  NEXT_PUBLIC_SNOWPLOW_COLLECTOR_URL=$(normalise_url "$NEXT_PUBLIC_SNOWPLOW_COLLECTOR_URL")

  step "Signals → Overview: the Signals API URL."
  note "  e.g. https://<hash>.signals.snowplowanalytics.com"
  ask SIGNALS_DEPLOYED_URL "Signals API base URL:"
  SIGNALS_DEPLOYED_URL=$(normalise_url "$SIGNALS_DEPLOYED_URL")

  write_env NEXT_PUBLIC_SNOWPLOW_COLLECTOR_URL "$NEXT_PUBLIC_SNOWPLOW_COLLECTOR_URL"
  write_env SIGNALS_DEPLOYED_URL "$SIGNALS_DEPLOYED_URL"

  printf '\n'
  note "collector : $NEXT_PUBLIC_SNOWPLOW_COLLECTOR_URL"
  note "Signals   : $SIGNALS_DEPLOYED_URL"
  confirm "Both correct?" && break
  warn "re-entering — press Enter at any prompt to keep the value shown"
done

# The interventions endpoint is the same host as the Signals API — the browser
# plugin just needs it under a NEXT_PUBLIC_ name to reach the client bundle.
write_env NEXT_PUBLIC_SIGNALS_INTERVENTIONS_ENDPOINT "$SIGNALS_DEPLOYED_URL"

say ""
say "Checking the API key and Signals URL together before going further:"
signals_preflight || {
  SKIPPED+=("Signals credential check failed — stage 9 fails the same way until fixed")
  confirm "Continue anyway?" || exit 1
}
pause
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
if begin "Storefront-side values (app ID, agent shared secret)" 2; then
say "Two values belong to the storefront rather than the Snowplow org, so they"
say "survive an org change. Only set here if missing."
if [[ -z "$(_env_value NEXT_PUBLIC_SNOWPLOW_APP_ID)" ]]; then
  write_env NEXT_PUBLIC_SNOWPLOW_APP_ID "atelier-storefront-dev"
  note "NEXT_PUBLIC_SNOWPLOW_APP_ID=atelier-storefront-dev (local); production uses atelier-storefront"
fi
if [[ -z "$(_env_value AGENT_SHARED_SECRET)" ]]; then
  write_env AGENT_SHARED_SECRET "$(openssl rand -hex 32)"
  note "AGENT_SHARED_SECRET generated (64 hex chars). You'll mirror this into the"
  note "CX Agent Studio tool auth later — see docs/setup-cx-agent-studio.md §3."
else
  note "AGENT_SHARED_SECRET already set — kept"
fi
pause
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
if begin "Seed the org with the tracking plan" 5; then
say "A fresh org has none of the demo's schemas, and the Signals publish in"
say "stage 9 hard-fails without them. Resource IDs are derived from the org ID,"
say "so seeding this org can't collide with any other org's IDs — including a"
say "previous trial's, if you're re-running this after an org change."
say ""
say "Dry run first — no credentials used, nothing written:"
run "dry run" npm --prefix storefront run seed:tracking-plans -- --dry-run || true
warn "snowplow-cli also reads ~/.config/snowplow/snowplow.yml. The env vars from"
warn "$ENV_FILE should win, but check the output below names the right org."
if confirm "Publish data structures (dev + prod) and the tracking plan to this org?"; then
  run "seed tracking plans" npm --prefix storefront run seed:tracking-plans || {
    warn "seeding failed. A version error means a schema's first version isn't"
    warn "1-0-0 — a fresh org has nothing to supersede. Fix the yml, then:"
    note "  ./scripts/setup-trial-org.sh --from 7"
    confirm "Continue to the next stage anyway?" || exit 1
  }
else
  SKIPPED+=("tracking-plan seed: npm --prefix storefront run seed:tracking-plans")
fi
pause
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
if begin "Regenerate the Snowtype helpers" 3; then
say "snowtype.config.json and snowtype/ are per-org and gitignored: the config"
say "names the org and the derived IDs of its own-schema event specifications,"
say "and the generated helpers embed the event-spec IDs read back from it. Both"
say "rebuild from the org ID in $ENV_FILE."
note "the event specification IDs are derived, not pasted — same UUIDv5 rule stage 7 used"
if confirm "Regenerate snowtype.config.json and storefront/snowtype/?"; then
  run "snowtype generate" npm --prefix storefront run snowtype:generate || {
    warn "generation failed. If it can't find the event specifications, stage 7 didn't"
    warn "finish — the plan must be published before snowtype can read it."
    SKIPPED+=("snowtype regenerate: npm --prefix storefront run snowtype:generate")
  }
else
  warn "storefront/src imports @/snowtype/snowplow — test, lint and build will"
  warn "fail until this runs, and the deploy in stage 12 ships stale spec IDs."
  SKIPPED+=("snowtype regenerate: npm --prefix storefront run snowtype:generate")
fi
pause
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
if begin "Publish the Signals config" 5; then
say "Attribute group, service, intervention and event log, via the Python SDK."
if [[ ! -x storefront/.venv/bin/python ]]; then
  run "create venv" python3 -m venv storefront/.venv || true
fi
run "install signals deps" sh -c 'cd storefront && .venv/bin/pip install -q -e .' || \
  warn "pip install failed — Python 3.11+ required"
say ""
say "Dry run (local validation only, no API call):"
run "signals dry run" npm --prefix storefront run signals:publish -- --dry-run || true
step "Confirm the printed objects name attribute group fashion_ecommerce_session_attributes"
step "and service fashion_ecommerce_demo."
if confirm "Publish the Signals config to this org?"; then
  PUBLISH_LOG=$(mktemp)
  run_logged "$PUBLISH_LOG" "signals publish" npm --prefix storefront run signals:publish || {
    if grep -q 'Signals API\] 401' "$PUBLISH_LOG"; then
      explain_key_scope
    elif grep -qi 'not in production\|Signals API\] 404' "$PUBLISH_LOG"; then
      warn "publish failed. A 404 'schema ... not in production' means stage 7"
      warn "didn't complete its prod promotion — re-run with --from 7."
    else
      warn "publish failed — read the error above. Missing env vars point back at"
      warn "stages 4-5; anything else, re-run the --dry-run to check the config."
    fi
    rm -f "$PUBLISH_LOG"
    confirm "Continue anyway?" || exit 1
  }
  rm -f "$PUBLISH_LOG"
else
  SKIPPED+=("Signals publish: npm --prefix storefront run signals:publish")
fi
pause
fi

# ── 10 ────────────────────────────────────────────────────────────────────
if begin "Verify the pipeline locally" 8; then
say "Browse the local storefront, then read the session's attributes back out"
say "of the org's Profile Store."
note "In a second terminal: npm --prefix storefront install && npm --prefix storefront run dev"
note "collector in use: $(_env_value NEXT_PUBLIC_SNOWPLOW_COLLECTOR_URL)"
open_url "http://localhost:3000"
step "Browse several products in at least one category, then add one to cart."
step "Open the browser console. Events should POST to the collector with no errors."
warn "A CORS error there means the collector URL lost its https:// — check $ENV_FILE."
step "Read the session ID from the on-page Signals debug panel (or the _sp_id"
step "cookie's second field)."
ask _SESSION_ID "Paste the domain_sessionid:"
if [[ -n "$_SESSION_ID" ]]; then
  printf '  %s$%s curl .../api/signals/attributes?identifier=%s\n' "$DIM" "$RESET" "$_SESSION_ID"
  curl -sS "http://localhost:3000/api/signals/attributes?identifier=${_SESSION_ID}" || \
    warn "request failed — is the dev server running?"
  printf '\n'
  step "Expect non-empty attributes matching what you browsed, e.g."
  step "favorite_category and total_product_views."
  confirm "Attributes look right?" || {
    warn "empty attributes usually mean the collector URL or app ID don't match"
    warn "a pipeline/app pair the org enriches for — recheck stages 5 and 6."
    SKIPPED+=("local end-to-end verification did not pass")
  }
else
  SKIPPED+=("local end-to-end verification (skipped — no session ID)")
fi
pause
fi

# ── 11 ────────────────────────────────────────────────────────────────────
if begin "Deploy the storefront to Vercel (optional)" 6; then
if ! confirm "Deploy to Vercel now? (skip if you only want to run locally)"; then
  SKIPPED+=("Vercel deployment — see docs/setup-snowplow-trial.md §7 when ready")
  pause
else
say "Production needs every value from .env.local except the -dev app ID."
say "NEXT_PUBLIC_CES_DEPLOYMENT_ID is set later, once the agent exists"
say "(docs/setup-cx-agent-studio.md §6)."
VERCEL_OK=0
if command -v vercel >/dev/null 2>&1; then
  if [[ ! -f storefront/.vercel/project.json ]]; then
    step "No Vercel project is linked yet. Running 'vercel link' — pick or create a"
    step "project and set Root Directory to storefront when asked."
    run "vercel link" vercel link --cwd storefront || true
  fi
  if vercel env ls production --cwd storefront >/dev/null 2>&1; then
    VERCEL_OK=1
    note "CLI can reach the linked project"
  else
    warn "the CLI can't read this project's settings — this Vercel login may"
    warn "not have access to the team that owns the project."
    step "Run 'vercel login' with the account that owns the deployment, then"
    step "re-run with --from 11, or paste the values into the dashboard instead."
    if confirm "Have you fixed the login and want to retry the check?"; then
      vercel env ls production --cwd storefront >/dev/null 2>&1 && VERCEL_OK=1
    fi
  fi
fi
if (( VERCEL_OK )); then
  if confirm "Overwrite every production env var via the Vercel CLI?"; then
    for key in SNOWPLOW_CONSOLE_ORG_ID SNOWPLOW_CONSOLE_API_KEY_ID SNOWPLOW_CONSOLE_API_KEY \
               SIGNALS_DEPLOYED_URL NEXT_PUBLIC_SNOWPLOW_COLLECTOR_URL \
               NEXT_PUBLIC_SIGNALS_INTERVENTIONS_ENDPOINT AGENT_SHARED_SECRET; do
      value=$(_env_value "$key")
      if [[ -z "$value" ]]; then warn "$key is empty in $ENV_FILE — skipping"; continue; fi
      # NEXT_PUBLIC_* reach the browser bundle by design, so they aren't sensitive.
      case "$key" in
        NEXT_PUBLIC_*) sensitive="" ;;
        *)             sensitive="--sensitive" ;;
      esac
      if printf '%s' "$value" | vercel env add "$key" production --force ${sensitive:+$sensitive} \
           --cwd storefront >/dev/null 2>&1; then
        printf '  %s✓%s set %s (production)\n' "$GREEN" "$RESET" "$key"
      else
        warn "failed to set $key — set it in the dashboard"
        SKIPPED+=("Vercel production env $key")
      fi
    done
    printf '%s' "atelier-storefront" | vercel env add NEXT_PUBLIC_SNOWPLOW_APP_ID production --force --cwd storefront >/dev/null 2>&1 || warn "failed to set NEXT_PUBLIC_SNOWPLOW_APP_ID"
    note "production NEXT_PUBLIC_SNOWPLOW_APP_ID=atelier-storefront (no -dev)"
  else
    SKIPPED+=("Vercel production env vars — not updated")
  fi
else
  open_url "https://vercel.com/dashboard"
  step "Project → Settings → Environment Variables → Production. Replace:"
  for key in SNOWPLOW_CONSOLE_ORG_ID SNOWPLOW_CONSOLE_API_KEY_ID SNOWPLOW_CONSOLE_API_KEY \
             SIGNALS_DEPLOYED_URL NEXT_PUBLIC_SNOWPLOW_COLLECTOR_URL \
             NEXT_PUBLIC_SIGNALS_INTERVENTIONS_ENDPOINT AGENT_SHARED_SECRET; do
    note "  - $key   (value is in $ENV_FILE)"
  done
  note "  - NEXT_PUBLIC_SNOWPLOW_APP_ID   (set to atelier-storefront, not the -dev value)"
  step "Mark the three SNOWPLOW_CONSOLE_* vars, SIGNALS_DEPLOYED_URL and"
  step "AGENT_SHARED_SECRET Sensitive."
  SKIPPED+=("Vercel production env vars set by hand — confirm every production value before deploying")
  pause "Done in the dashboard — press Enter."
fi
pause
fi
fi

# ── 12 ────────────────────────────────────────────────────────────────────
if begin "Deploy and verify the live site" 6; then
if (( ${#SKIPPED[@]} )) && printf '%s\n' "${SKIPPED[@]}" | grep -q '^Vercel deployment'; then
  note "skipped — no Vercel deployment this run"
else
  say "Deploy from the CLI (or via a Vercel Git integration if you set one up)."
  warn "Vercel env changes only apply to the NEXT deploy — stage 11 must be done."
  if command -v vercel >/dev/null 2>&1 && confirm "Deploy to production now (vercel --prod)?"; then
    run "vercel --prod" vercel --prod --cwd storefront || \
      SKIPPED+=("production deploy: vercel --prod --cwd storefront")
  else
    SKIPPED+=("production deploy: vercel --prod --cwd storefront")
  fi
  ask _STOREFRONT_URL "Live storefront URL (https://...):"
  if [[ -n "$_STOREFRONT_URL" ]]; then
    _SECRET=$(_env_value AGENT_SHARED_SECRET)
    if [[ -z "$_SECRET" ]]; then
      warn "AGENT_SHARED_SECRET missing from $ENV_FILE — can't run the smoke test"
      SKIPPED+=("verify:deploy against $_STOREFRONT_URL")
    else
      AGENT_SHARED_SECRET="$_SECRET" npm --prefix storefront run verify:deploy -- "$_STOREFRONT_URL" || {
        warn "one or more checks failed — see docs/setup-snowplow-trial.md troubleshooting"
        SKIPPED+=("verify:deploy reported failures against $_STOREFRONT_URL")
      }
    fi
    step "Then repeat the browser walkthrough on the live URL: browse, add to cart,"
    step "grab the session ID, and confirm /api/agent/context reflects it."
    open_url "$_STOREFRONT_URL"
  fi
fi
pause
fi

note "Next: build the agent — docs/setup-cx-agent-studio.md. It needs the storefront"
note "URL and AGENT_SHARED_SECRET from $ENV_FILE."
note "Expect no git diff from any of this: .env.local, snowtype.config.json and"
note "snowtype/ are all gitignored. Check with: git status --short"
finish
